pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != c.ceoAddress());
        // Ensure contract is initialized so the bug path is reachable (DrugDealer has no initialization check, but make state valid)
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.seedMarket{value: 1 ether}(1000);

        // Record the original ceoAddress
        address originalCeo = c.ceoAddress();

        // The attack: a non-CEO calls DrugDealer()
        vm.prank(caller);
        c.DrugDealer();

        address newCeo = c.ceoAddress();
        // Property: ceoAddress must remain unchanged when called by a non-CEO
        assertTrue(newCeo == originalCeo);
    }
}

