pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Restrict caller to any address except the deployer (this contract)
        vm.assume(caller != address(this));

        // Record the current ceoAddress before the call
        address ceoBefore = c.ceoAddress();

        // Make the fuzzed caller attempt to become CEO
        vm.prank(caller);
        c.DrugDealer();

        // The ceoAddress MUST NOT have changed from its original value
        assertEq(c.ceoAddress(), ceoBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract via seedMarket so that the ceoAddress is set
        // and the contract is in a usable state. The deployer of C (this test contract)
        // is NOT the hardcoded ceoAddress.
        // We first need to become the hardcoded ceoAddress to call seedMarket and DrugDealer.
        address hardcodedCeo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.deal(hardcodedCeo, 1 ether);
        vm.prank(hardcodedCeo);
        c.seedMarket{value: 1 ether}(1000);
        // Now hardcodedCeo calls DrugDealer() to set the CEO to itself (as per reference logic).
        vm.prank(hardcodedCeo);
        c.DrugDealer();
    }

    function testFuzz_property(address caller) public {
        // We only care about callers that are NOT the current ceoAddress.
        address currentCeo = c.ceoAddress();
        vm.assume(caller != currentCeo);
        // Also ensure caller is not address(0) to avoid any weird edge cases.
        vm.assume(caller != address(0));

        // Record the ceoAddress before the call.
        address ceoBefore = c.ceoAddress();

        // The caller attempts to become CEO via DrugDealer.
        vm.prank(caller);
        c.DrugDealer();

        // After the call, ceoAddress must remain unchanged.
        address ceoAfter = c.ceoAddress();
        assertEq(ceoAfter, ceoBefore, "ceoAddress changed by non-CEO caller");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address attacker) public {
        require(attacker != 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        bool reverted = false;
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        if (!ok) reverted = true;
        assert(reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        try c.DrugDealer() { reverted = false; } catch { reverted = true; }
        assert(reverted != (caller == c.ceoAddress()));
    }
    receive() external payable {}
}
